class MinMaxStack {
    private static class Node {
        int value;
        int minSoFar;
        int maxSoFar;
        Node next;

        Node(int value, int minSoFar, int maxSoFar, Node next) {
            this.value = value;
            this.minSoFar = minSoFar;
            this.maxSoFar = maxSoFar;
            this.next = next;
        }
    }

    private Node top;

    public void push(int value) {
        int newMin = (top == null) ? value : Math.min(value, top.minSoFar);
        int newMax = (top == null) ? value : Math.max(value, top.maxSoFar);
        top = new Node(value, newMin, newMax, top);
    }

    public int pop() {
        if (top == null) throw new IllegalStateException("Stack underflow");
        int value = top.value;
        top = top.next;
        return value;
    }

    public int getRange() {
        if (top == null) throw new IllegalStateException("Stack is empty");
        return top.maxSoFar - top.minSoFar;
    }

    public static void main(String[] args) {
        MinMaxStack stack = new MinMaxStack();
        stack.push(5);
        System.out.println("Range: " + stack.getRange()); // 0
        stack.push(2);
        System.out.println("Range: " + stack.getRange()); // 3
        stack.push(8);
        System.out.println("Range: " + stack.getRange()); // 6
        stack.pop();
        System.out.println("Range: " + stack.getRange()); // 3
    }
}
```

**Feature chosen: `getRange()`** — returns max − min of all elements currently in the stack.

